style.css:
@-moz-document domain("open.spotify.com") {
@font-face {
  font-family: "Invader Zim";
  src: url("INVADER.TTF") format("truetype");
}

body,
.Root,
#main,
.encore-dark-theme,
.main-view-container,
.main-view-container__scroll-node,
.Root__main-view,
.Root__now-playing-bar {
  background:
    linear-gradient(
      rgba(5, 0, 10, 0.72),
      rgba(28, 0, 45, 0.86)
    ),
    url("https://pbs.twimg.com/media/EbzONYCXgAER8ju.jpg")
    center center / cover fixed no-repeat !important;
}

.Root__nav-bar,
.Root__right-sidebar,
.main-topBar-background,
.main-view-container__scroll-node-child,
.main-home-homeHeader,
.main-nowPlayingBar-container,
.playlist-playlist-playlistContent {
  background: rgba(10, 0, 18, 0.58) !important;
  backdrop-filter: blur(10px) saturate(135%) !important;
}

* {
  font-family: "Invader Zim", "CircularSp", "Helvetica Neue", Arial, sans-serif !important;
  letter-spacing: 0.4px;
}

h1,
h2,
h3,
[data-testid="entityTitle"],
.main-entityHeader-title h1 {
  color: #b9ff4a !important;
  text-shadow:
    0 0 6px #39ff14,
    0 0 14px #7f00ff;
}

span,
p,
a,
button {
  color: #f2eaff !important;
}

a:hover,
.main-navBar-navBarLinkActive,
.main-trackList-rowTitle:hover {
  color: #7dff2a !important;
  text-shadow: 0 0 8px #39ff14;
}

.main-card-card,
.main-shelf-shelfItem,
.BoxComponent-group-card {
  background: rgba(22, 0, 35, 0.72) !important;
  border: 1px solid rgba(185, 255, 74, 0.25) !important;
  box-shadow: 0 0 18px rgba(127, 0, 255, 0.25);
}

button,
.ButtonInner-sc-14ud5tc-0 {
  border-radius: 12px !important;
}

[data-testid="play-button"] {
  background: #7dff2a !important;
  box-shadow:
    0 0 10px #39ff14,
    0 0 22px #7f00ff !important;
}

.progress-bar__fg,
.playback-bar__progress-time-elapsed,
[data-testid="progress-bar"] div {
  background-color: #7dff2a !important;
}

.Root__top-container,
.main-view-container__scroll-node,
.main-view-container__scroll-node-child {
  background-color: transparent !important;
}
}
